"""Replayable telemetry validation pipeline for one stream.

A stream owns independent state: measured counters, demands, the active routing
plan, the process-local repair cache and its frozen snapshots.  Events are the
only way that state moves, and every answer is derived from the integer replay
policy in PROTOCOL.md -- never from wall-clock, filesystem or process state.
"""

from .common_utils import Plan, Topology, WEIGHT_TOTAL, is_int
from .dtp import RepairEngine
from .snapshot_cache import RepairCache, SnapshotStore, normalize_inputs
from .validate import Validator

CELL_ALLOWED = frozenset(("perturbed", "ground_truth", "corrected", "confidence"))
DEMAND_FIELDS = frozenset(("op", "demands", "counters"))


class CrossCheck:
    """Unified repair/validation pipeline for a single topology."""

    def __init__(self, topology):
        self.topology = Topology(topology)
        self.repairer = RepairEngine(self.topology)
        self.validator = Validator(self.topology)
        self.settings = None
        self.counters = {}
        self.demands = {}
        self.plan = None
        self.plan_identity = None
        self.cache = RepairCache(0)
        self.snapshots = SnapshotStore()
        self._loads = None
        self._dirty = True

    # --------------------------------------------------------------- lifecycle
    def _configure(self, settings):
        """Settings are fixed per stream; snapshots and memoization are fresh."""
        self.settings = settings
        self.cache = RepairCache(settings["cache_slots"])
        self.snapshots = SnapshotStore()
        self.counters = {}
        self.demands = {}
        self.plan = None
        self.plan_identity = None
        self._loads = None
        self._dirty = True

    # ----------------------------------------------------------- predictions
    def loads(self):
        """Current predicted load per flow, or None where none is expected.

        External flows always carry their demand marginal.  Internal flows carry
        the floored weighted path sum only when a routing plan is active; with a
        null plan they have no expectation at all.  Expectations are never
        clamped here -- the clamp belongs to the repair prediction vote.
        """
        if not self._dirty and self._loads is not None:
            return self._loads
        flows = self.topology.flows
        table = [None] * len(flows)
        outgoing = {}
        incoming = {}
        for (src, dst), value in self.demands.items():
            if value:
                outgoing[src] = outgoing.get(src, 0) + value
                incoming[dst] = incoming.get(dst, 0) + value
        for flow in flows:
            if flow.src == -1:
                table[flow.index] = outgoing.get(flow.dst, 0)
            elif flow.dst == -1:
                table[flow.index] = incoming.get(flow.src, 0)
        if self.plan is not None:
            weighted = self.plan.internal_loads(self.demands)
            # Floor exactly once, after every demand/path contribution is added.
            for flow in flows:
                if flow.src != -1 and flow.dst != -1:
                    table[flow.index] = weighted.get(flow.index, 0) // WEIGHT_TOTAL
        self._loads = table
        self._dirty = False
        return table

    def identity(self):
        """Semantic repair key: inputs, routes and repair settings only."""
        return (normalize_inputs(self.counters, self.demands, self.plan_identity),
                self.settings["seed"], self.settings["trials"],
                self.settings["epsilon"])

    # ----------------------------------------------------------------- events
    def apply_patch(self, event):
        """Validate then, only if wholly legal, commit the atomic update."""
        if set(event) != DEMAND_FIELDS:
            return False
        demand_list = event["demands"]
        counter_map = event["counters"]
        if type(demand_list) is not list or type(counter_map) is not dict:
            return False
        topo = self.topology
        staged_demands = {}
        for entry in demand_list:
            if type(entry) is not list or len(entry) != 3:
                return False
            src, dst, value = entry
            if not (is_int(src) and is_int(dst) and is_int(value)):
                return False
            bound = topo.demand_bound(src, dst)
            if bound is None:
                return False              # pair not between distinct externals
            if (src, dst) in staged_demands:
                return False              # repeated pair
            if value < 0 or value > bound:
                return False              # outside the pair's capacity bound
            staged_demands[(src, dst)] = value
        staged_counters = {}
        for key, cell in counter_map.items():
            if key not in topo.key_cap:
                return False              # unknown counter key
            if cell is None:
                staged_counters[key] = None
